//! pcb_toolkit's calculators for the browser.
//!
//! `dispatch.rs` is the desktop app's Tauri backend, generated by `scripts/sync_vendor.py`
//! with only the Tauri attributes removed. This file is the whole web-specific layer: the
//! same three commands, with JSON text in and out so values cross the boundary exactly as
//! they did over Tauri's IPC.

mod dispatch;

use wasm_bindgen::prelude::*;

/// Run one calculator. `params_json` is the `{ key: value }` object the form sends; the
/// result is the calculator's output object as JSON. Errors are plain strings for display.
#[wasm_bindgen]
pub fn calculate(id: &str, params_json: &str) -> Result<String, String> {
    let params = serde_json::from_str(params_json).map_err(|e| format!("bad parameters: {e}"))?;
    let value = dispatch::calculate(id.to_owned(), params)?;
    serde_json::to_string(&value).map_err(|e| e.to_string())
}

/// The built-in substrate database, as a JSON array of `{ name, er, tg }`.
#[wasm_bindgen]
pub fn list_materials() -> String {
    serde_json::to_string(&dispatch::list_materials()).unwrap_or_else(|_| "[]".to_owned())
}

/// AWG labels, largest to smallest, as a JSON array of strings.
#[wasm_bindgen]
pub fn list_awg() -> String {
    serde_json::to_string(&dispatch::list_awg()).unwrap_or_else(|_| "[]".to_owned())
}
